00226 static inline bool isAlignedBins( CodingStatisticsType statT ) { return statT == STATS__CABAC_BITS__ALIGNED_SIGN_BIT || statT == STATS__CABAC_BITS__ALIGNED_ESCAPE_BITS; }
00227 
00228 static const uint32_t CODING_STATS_NUM_WIDTHS     = 20; // just define the number of widths and heigts as 15
00229 static const uint32_t CODING_STATS_NUM_HEIGHTS    = 20;
00230 static const uint32_t CODING_STATS_NUM_SIZES      = CODING_STATS_NUM_HEIGHTS * CODING_STATS_NUM_WIDTHS;
00231 static const uint32_t CODING_STATS_NUM_SUBCLASSES = CODING_STATS_NUM_SIZES * (1 + MAX_NUM_COMPONENT + MAX_NUM_CHANNEL_TYPE);
00232 
00233 class CodingStatisticsClassType
00234 {
00235 public:
00236 
00237   CodingStatisticsClassType( const CodingStatisticsType t ) : type( t ), subClass( 0 )
00238   {
00239   }
00240 
00241   CodingStatisticsClassType( const CodingStatisticsType t, const uint32_t width, const uint32_t height ) : type( t ), subClass( gp_sizeIdxInfo->idxFrom( height ) * CODING_STATS_NUM_WIDTHS + gp_sizeIdxInfo->idxFrom( width ) )
00242   {
00243   }
00244 
00245   CodingStatisticsClassType( const CodingStatisticsType t, const int width, const int height ) : type( t ), subClass( gp_sizeIdxInfo->idxFrom( height ) * CODING_STATS_NUM_WIDTHS + gp_sizeIdxInfo->idxFrom( width ) )
00246   {
00247   }
00248 
00249   CodingStatisticsClassType( const CodingStatisticsType t, const ComponentID cid ) : type( t ), subClass( ( cid + 1 ) * CODING_STATS_NUM_SIZES )
00250   {
00251   }
00252 
00253   CodingStatisticsClassType( const CodingStatisticsType t, const ChannelType chid ) : type( t ), subClass( ( chid + MAX_NUM_COMPONENT + 1 ) * CODING_STATS_NUM_SIZES )
00254   {
00255   }
00256 
00257   CodingStatisticsClassType( const CodingStatisticsType t, const uint32_t width, const uint32_t height, const ComponentID cid ) : type( t ), subClass( ( cid + 1 ) * CODING_STATS_NUM_SIZES + gp_sizeIdxInfo->idxFrom( height ) * CODING_STATS_NUM_WIDTHS + gp_sizeIdxInfo->idxFrom( width ) )
00258   {
00259   }
00260 
00261   CodingStatisticsClassType( const CodingStatisticsType t, const uint32_t width, const uint32_t height, const ChannelType chid ) : type( t ), subClass( ( chid + MAX_NUM_COMPONENT + 1 ) * CODING_STATS_NUM_SIZES + gp_sizeIdxInfo->idxFrom( height ) * CODING_STATS_NUM_WIDTHS + gp_sizeIdxInfo->idxFrom( width ) )
00262   {
00263   }
00264 
00265   ~CodingStatisticsClassType()
00266   {
00267     // should not be relevant, but it looks like some instances are used after they are destroyed
00268     type = STATS__CABAC_BITS__INVALID;
00269     subClass = 0;
00270   }
00271 
00272   static uint32_t GetSubClassWidth( const uint32_t subClass )
00273   {
00274     return subClass % CODING_STATS_NUM_WIDTHS;
00275   }
00276 
00277   static uint32_t GetSubClassHeight( const uint32_t subClass )
00278   {
00279     return ( subClass % CODING_STATS_NUM_SIZES ) / CODING_STATS_NUM_WIDTHS;
00280   }
00281 
00282   static const char *GetSubClassString( const uint32_t subClass )
00283   {
00284     CHECK( subClass >= CODING_STATS_NUM_SUBCLASSES, "Subclass does not exist" );
00285     static const char *strings[1 + MAX_NUM_COMPONENT + MAX_NUM_CHANNEL_TYPE] = { "-", "Y", "Cb", "Cr", "Luma", "Chroma" };
00286     return strings[subClass / CODING_STATS_NUM_SIZES];
00287   }
00288 
00289   CodingStatisticsType type;
00290   uint32_t subClass;
00291 };
