00295 class CodingStatistics
00296 {
00297 public:
00298 
00299   struct StatLogValue
00300   {
00301     uint32_t values[512 + 1];
00302     StatLogValue()
00303     {
00304       const double es = double( CODINGSTATISTICS_ENTROPYSCALE );
00305 
00306       values[0] = 0;
00307 
00308       for( uint32_t i = 1; i < sizeof( values ) / sizeof( uint32_t ); i++ )
00309       {
00310         values[i] = uint32_t( log( double( i ) )*es / log( 2.0 ) );
00311       }
00312     }
00313   };
00314 
00315   struct SStat
00316   {
00317     SStat() : bits( 0 ), count( 0 ), sum( 0 ), classCount( 0 ) { }
00318 
00319     int64_t bits;
00320     int64_t count;
00321     int64_t sum;
00322     int64_t classCount;
00323 
00324     void clear() { bits = 0; count = 0; sum = 0; classCount = 0; }
00325 
00326     SStat &operator+=( const SStat &src )
00327     {
00328       bits += src.bits; count += src.count; sum += src.sum; classCount += src.classCount; return *this;
00329     }
00330 
00331 #if RExt__DECODER_DEBUG_TOOL_MAX_FRAME_STATS
00332     SStat &operator-=(const SStat &src)
00333     {
00334       bits -= src.bits; count -= src.count; sum -= src.sum; classCount -= src.classCount; return *this;
00335     }
00336 #endif
00337   };
00338 
00339   struct StatTool
00340   {
00341     StatTool() : count( 0 ), pixels( 0 ), classCount( 0 ) { }
00342 
00343     int64_t  count;
00344     int64_t  pixels;
00345     int64_t  classCount;
00346 
00347     void clear() { count = 0; pixels = 0; classCount = 0; }
00348 
00349     StatTool &operator+=( const StatTool &src )
00350     {
00351       count += src.count; pixels += src.pixels; classCount += src.classCount; return *this;
00352     }
00353   };
00354 
