00452   static void OutputLine( const char *pName, const char sep, const char *pWidthString, const char *pHeightString, const char *pSubClassStr, const StatTool &sTool, uint64_t totalPixels )
00453   {
00454     const double ratio = 100.0 * sTool.pixels / ( double ) totalPixels;
00455     printf( "%c%-45s%c  %6s %6s %6s %12" PRId64 "     %12" PRId64 "       %11.2f%%%c\n",
00456             sep == '~' ? '[' : ' ', pName, sep, pWidthString, pHeightString, pSubClassStr,
00457             sTool.count, sTool.pixels, ratio, sep == '~' ? ']' : ' ' );
00458   }
