00460   static void OutputLine( const char *pName, const char sep, uint32_t wIdx, uint32_t hIdx, const char *pSubClassStr, const StatTool &sTool, uint64_t totalPixels )
00461   {
00462     const double ratio = 100.0 * sTool.pixels / ( double ) totalPixels;
00463     printf( "%c%-45s%c  %6d %6d %6s %12" PRId64 "     %12" PRId64 "       %11.2f%%%c\n",
00464             sep == '~' ? '[' : ' ', pName, sep, gp_sizeIdxInfo->sizeFrom( wIdx ), gp_sizeIdxInfo->sizeFrom( hIdx ), pSubClassStr,
00465             sTool.count, sTool.pixels, ratio, sep == '~' ? ']' : ' ' );
00466   }
