00468   static void OutputDashedLine( const char *pText )
00469   {
00470     printf( "--%s", pText );
00471     uint32_t tot = 0;
00472     for( ; pText[tot] != 0; tot++ );
00473 
00474     tot += 2;
00475     for( ; tot < 202; tot++ )
00476     {
00477       printf( "-" );
00478     }
00479     printf( "\n" );
00480   }
