00482   void OutputBitStats()
00483   {
00484     const int64_t es = CODINGSTATISTICS_ENTROPYSCALE;
00485 
00486     int64_t countTotal = 0;
00487     int64_t classCounts[STATS__NUM_STATS];
00488     std::fill_n( classCounts, ( size_t ) STATS__NUM_STATS, 0 );
00489 
00490 #if RExt__DECODER_DEBUG_TOOL_MAX_FRAME_STATS
00491     SStat_max &max = GetStatisticMax();
00492 #endif
00493 
00494     int64_t cr = 0; // CABAC remainder, which is added to "STATS__CABAC_INITIALISATION"
00495     {
00496       int64_t totalCABACbits = 0, roundedCABACbits = 0;
00497       for( int i = STATS__NAL_UNIT_PACKING; i < STATS__NUM_STATS; i++ )
00498       {
00499         int64_t classCount = 0;
00500 
00501         for( uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c++ )
00502         {
00503           totalCABACbits    += data.statistics[i][c].bits;
00504           roundedCABACbits  += data.statistics[i][c].bits / es;
00505           classCount        += data.statistics[i][c].count;
00506         }
00507 
00508         for( uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c++ )
00509         {
00510           data.statistics[i][c].classCount = classCount;
00511         }
00512 
00513         classCounts[i] = classCount;
00514         countTotal    += classCount;
00515       }
00516       int64_t remainder = totalCABACbits - roundedCABACbits * es;
00517       cr = ( remainder + es / 2 ) / es;
00518     }
00519 
00520     classCounts[0] = countTotal;
00521 
00522     printf( "Note %s will be excluded from the total as it should be the sum of all the other entries (except for %s)\n", getName( STATS__NAL_UNIT_TOTAL_BODY ), getName( STATS__NAL_UNIT_PACKING ) );
00523     printf( " %-45s-   Width Height   Type  CABAC quote  CABAC count    CABAC Sum   CABAC bits  CABAC ratio     EP Count       EP Sum      EP bits   Total bits ( Total bytes)\n", "Decoder statistics" );
00524 
00525     OutputDashedLine( "" );
00526     SStat cabacTotalBits, epTotalBits;
00527 
00528     cabacTotalBits.classCount = countTotal;
00529     epTotalBits   .classCount = countTotal;
00530 
00531     SStat statTotals_cabac[CODING_STATS_NUM_SUBCLASSES];
00532     SStat statTotals_ep   [CODING_STATS_NUM_SUBCLASSES];
00533 
00534     for( int i = 0; i < STATS__NUM_STATS; i++ )
00535     {
00536       SStat cabacSubTotal, epSubTotal;
00537       cabacSubTotal.classCount = classCounts[i];
00538       epSubTotal   .classCount = classCounts[i];
00539       bool bHadClassifiedEntry = false;
00540 
00541       const char *pName = getName( CodingStatisticsType( i ) );
00542 
00543       for( uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c++ )
00544       {
00545         SStat &sCABACorig = data.statistics[i][c];
00546         SStat &sEP        = data.statistics_ep[i][c];
00547 
00548         if( sCABACorig.bits == 0 && sEP.bits == 0 )
00549         {
00550           continue;
00551         }
00552 
00553         SStat sCABAC;
00554         {
00555           int64_t thisCABACbits = sCABACorig.bits / es;
00556           if( i == STATS__CABAC_INITIALISATION && sCABACorig.bits != 0 )
00557           {
00558             thisCABACbits += cr;
00559 #if EPBINCOUNT_FIX
00560             sCABACorig.count = 0;
00561 #endif
00562             cr = 0;
00563           }
00564           sCABAC.bits       = thisCABACbits;
00565           sCABAC.count      = sCABACorig.count;
00566           sCABAC.sum        = sCABACorig.sum;
00567           sCABAC.classCount = classCounts[i];
00568         }
00569 #if EPBINCOUNT_FIX
00570         if (i == STATS__BYTE_ALIGNMENT_BITS || i == STATS__TRAILING_BITS || i == STATS__NAL_UNIT_HEADER_BITS || i == STATS__EMULATION_PREVENTION_3_BYTES)
00571         {
00572           sEP.count = 0;
00573         }
00574 #endif
00575         uint32_t wIdx = CodingStatisticsClassType::GetSubClassWidth( c );
00576         uint32_t hIdx = CodingStatisticsClassType::GetSubClassHeight( c );
00577         OutputLine( pName, ':', wIdx, hIdx, CodingStatisticsClassType::GetSubClassString( c ), sCABAC, sEP );
00578         cabacSubTotal += sCABAC;
00579         epSubTotal    += sEP;
00580 
00581         if( i != STATS__NAL_UNIT_TOTAL_BODY )
00582         {
00583           cabacTotalBits      += sCABAC;
00584           epTotalBits         += sEP;
00585           statTotals_cabac[c] += sCABAC;
00586           statTotals_ep[c]    += sEP;
00587 
00588         }
00589         bHadClassifiedEntry = bHadClassifiedEntry || ( c != 0 );
00590       }
00591 
00592       if( bHadClassifiedEntry )
00593       {
00594         cabacSubTotal.classCount = classCounts[i];
00595         OutputLine( pName, '~', "~~ST~~", "~~ST~~", "~~ST~~", cabacSubTotal, epSubTotal );
00596 
00597 #if RExt__DECODER_DEBUG_TOOL_MAX_FRAME_STATS
00598         // For TRF
00599         if ((i == STATS__CABAC_BITS__SIG_COEFF_MAP_FLAG) || (i == STATS__CABAC_BITS__PAR_FLAG)
00600             || (i == STATS__CABAC_BITS__GT1_FLAG) || (i == STATS__CABAC_BITS__GT2_FLAG)
00601             || (i == STATS__CABAC_BITS__ESCAPE_BITS))
00602         {
00603           max.acc_trf_CABAC_state += cabacSubTotal;
00604           max.acc_trf_EP_state += epSubTotal;
00605         }
00606 #endif
00607 
00608       }
00609       if( i == STATS__NAL_UNIT_TOTAL_BODY )
00610       {
00611         OutputDashedLine( "" );
00612       }
00613     }
00614     OutputDashedLine( "" );
00615     OutputLine( "CABAC Sub-total", '~', "~~ST~~", "~~ST~~", "~~ST~~", cabacTotalBits, epTotalBits );
00616 
00617     OutputDashedLine( "CAVLC HEADER BITS" );
00618     SStat cavlcTotalBits;
00619     for( std::map<std::string, SStat>::iterator it = data.mappings_ep.begin(); it != data.mappings_ep.end(); it++ )
00620     {
00621       SStat s = it->second;
00622       cavlcTotalBits += s;
00623       OutputLine( it->first.c_str(), ':', "-", "-", "-", s );
00624     }
00625 
00626     OutputDashedLine( "" );
00627     OutputLine( "CAVLC Header Sub-total", '~', "~~ST~~", "~~ST~~", "~~ST~~", cavlcTotalBits );
00628 
00629     // Now output the breakdowns
00630     OutputDashedLine( "CABAC Break down by size" );
00631     for( uint32_t w = 0; w < CODING_STATS_NUM_WIDTHS; w++ )
00632     {
00633       for( uint32_t h = 0; h < CODING_STATS_NUM_HEIGHTS; h++ )
00634       {
00635         SStat subTotalCabac, subTotalEP;
00636         for( uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c += CODING_STATS_NUM_SIZES )
00637         {
00638           subTotalCabac += statTotals_cabac[c + h * CODING_STATS_NUM_WIDTHS + w];
00639           subTotalEP    += statTotals_ep   [c + h * CODING_STATS_NUM_WIDTHS + w];
00640         }
00641         if( subTotalCabac.bits != 0 || subTotalEP.bits != 0 )
00642         {
00643           OutputLine( "CABAC by size Sub-total", '=', w, h, "All", subTotalCabac, subTotalEP );
00644         }
00645       }
00646     }
00647     OutputDashedLine( "Break down by component/Channel type" );
00648     for( uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c += CODING_STATS_NUM_SIZES )
00649     {
00650       SStat subTotalCabac, subTotalEP;
00651       for( uint32_t w = 0; w < CODING_STATS_NUM_WIDTHS; w++ )
00652       {
00653         for( uint32_t h = 0; h < CODING_STATS_NUM_HEIGHTS; h++ )
00654         {
00655           subTotalCabac += statTotals_cabac[c + h * CODING_STATS_NUM_WIDTHS + w];
00656           subTotalEP    += statTotals_ep   [c + h * CODING_STATS_NUM_WIDTHS + w];
00657         }
00658       }
00659       if( subTotalCabac.bits != 0 || subTotalEP.bits != 0 )
00660       {
00661         OutputLine( "CABAC by type Sub-total", '=', "-", "-", CodingStatisticsClassType::GetSubClassString( c ), subTotalCabac, subTotalEP );
00662       }
00663     }
00664     OutputDashedLine( "Break down by size and component/Channel type" );
00665     for( uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c += CODING_STATS_NUM_SIZES )
00666     {
00667       for( uint32_t w = 0; w < CODING_STATS_NUM_WIDTHS; w++ )
00668       {
00669         for( uint32_t h = 0; h < CODING_STATS_NUM_HEIGHTS; h++ )
00670         {
00671           SStat subTotalCabac, subTotalEP;
00672           subTotalCabac += statTotals_cabac[c + h * CODING_STATS_NUM_WIDTHS + w];
00673           subTotalEP    += statTotals_ep   [c + h * CODING_STATS_NUM_WIDTHS + w];
00674 
00675           if( subTotalCabac.bits != 0 || subTotalEP.bits != 0 )
00676           {
00677             OutputLine( "CABAC by size and type Sub-total", '=', w, h, CodingStatisticsClassType::GetSubClassString( c ), subTotalCabac, subTotalEP );
00678           }
00679         }
00680       }
00681     }
00682 
00683     OutputDashedLine( "" );
00684     cabacTotalBits.classCount = countTotal;
00685     OutputLine      ( "CABAC Sub-total",        '~', "~~ST~~", "~~ST~~", "~~ST~~", cabacTotalBits, epTotalBits );
00686     OutputLine      ( "CAVLC Header Sub-total", '~', "~~ST~~", "~~ST~~", "~~ST~~", cavlcTotalBits );
00687     OutputDashedLine( "GRAND TOTAL" );
00688     epTotalBits += cavlcTotalBits;
00689     OutputLine      ( "TOTAL",                  '~', "~~GT~~", "~~GT~~", "~~GT~~", cabacTotalBits, epTotalBits );
00690 #if RExt__DECODER_DEBUG_TOOL_MAX_FRAME_STATS
00691     OutputDashedLine("");
00692     OutputLine("CABAC MAX FRAME stat", '~', "~~ST~~", "~~ST~~", "~~ST~~", max.max_CABAC_state, max.max_EP_state);
00693     OutputLine("CABAC MAX FRAME TRF stat", '~', "~~ST~~", "~~ST~~", "~~ST~~", max.trf_CABAC_state, max.trf_EP_state);
00694     OutputLine("CABAC Accumulated TRF stat", '~', "~~ST~~", "~~ST~~", "~~ST~~", max.acc_trf_CABAC_state, max.acc_trf_EP_state);
00695 #endif
00696   }
