00698   void OutputToolStats()
00699   {
00700     printf("\n");
00701     printf( " %-45s-   Width Height   Type        Count  Impacted pixels  %% Impacted pixels\n", "Tools statistics" );
00702     OutputDashedLine( "" );
00703 
00704     const uint64_t toolCount = STATS__TOOL_TOTAL - (STATS__TOOL_TOTAL_FRAME + 1);
00705     StatTool subTotalTool[toolCount];
00706     StatTool statTotalTool[toolCount][CODING_STATS_NUM_SUBCLASSES];
00707     uint64_t totalPixels = GetStatisticTool( STATS__TOOL_TOTAL_FRAME ).pixels;
00708     for( int i = 0; i < toolCount; i++ )
00709     {
00710       const int type = i + (STATS__TOOL_TOTAL_FRAME + 1);
00711       const char *pName = getName( CodingStatisticsType( type ) );
00712 
00713       for( uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c++ )
00714       {
00715         StatTool &sTool   = data.statistics_tool[type][c];
00716         if( sTool.count == 0 )
00717         {
00718           continue;
00719         }
00720 
00721         uint32_t wIdx = CodingStatisticsClassType::GetSubClassWidth( c );
00722         uint32_t hIdx = CodingStatisticsClassType::GetSubClassHeight( c );
00723         OutputLine( pName, ':', wIdx, hIdx, CodingStatisticsClassType::GetSubClassString( c ), sTool, totalPixels );
00724 
00725         statTotalTool[i][c] += sTool;
00726         subTotalTool[i] += sTool;
00727       }
00728 
00729       if (subTotalTool[i].count != 0)
00730       {
00731         OutputLine( pName, '~', "~~ST~~", "~~ST~~", "~~ST~~", subTotalTool[i], totalPixels );
00732       }
00733     }
00734 
00735     for( int i = 0; i < toolCount; i++ )
00736     {
00737       const int type = i + (STATS__TOOL_TOTAL_FRAME + 1);
00738       const char *pName = getName( CodingStatisticsType( type ) );
00739 
00740       if (subTotalTool[i].count != 0)
00741         OutputDashedLine( "Break down by tool/Channel type" );
00742 
00743       for( uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c += CODING_STATS_NUM_SIZES )
00744       {
00745         StatTool typeTotalTool;
00746         for( uint32_t w = 0; w < CODING_STATS_NUM_WIDTHS; w++ )
00747         {
00748           for( uint32_t h = 0; h < CODING_STATS_NUM_HEIGHTS; h++ )
00749             typeTotalTool += statTotalTool[i][c + h * CODING_STATS_NUM_WIDTHS + w];
00750         }
00751 
00752         if( typeTotalTool.count != 0 )
00753         {
00754           OutputLine( pName, '=', "-", "-", CodingStatisticsClassType::GetSubClassString( c ), typeTotalTool, totalPixels );
00755         }
00756       }
00757     }
00758   }
