00808   static int getNumOnes( int bins )
00809   {
00810     CHECK( bins < 0, "Bins should not be nagative" );
00811 
00812     int count = 0;
00813     while( bins )
00814     {
00815       count += bins & 1;
00816       bins >>= 1;
00817     }
00818     return count;
00819   }
00820 
00821   static void IncrementStatisticEP( const CodingStatisticsClassType &stat, const int numBits, const int value )
00822   {
00823     CHECK( stat.type == STATS__CABAC_BITS__INVALID, "Should never be used." );
00824     SStat &s = GetStatisticEP( stat );
00825     s.bits  += numBits;
00826 #if EPBINCOUNT_FIX
00827     s.count += numBits;
00828 #else
00829     s.count++;
00830 #endif
00831     s.sum   += getNumOnes( value );
00832   }
00833 
