00858   static void IncrementStatisticTool( const CodingStatisticsClassType &stat )
00859   {
00860     CHECK( stat.type < STATS__TOOL_TOTAL_FRAME || stat.type >= STATS__TOOL_TOTAL, "Should never be used." );
00861     StatTool &s = GetStatisticTool( stat );
00862     s.count++;
00863 
00864     uint32_t wIdx = CodingStatisticsClassType::GetSubClassWidth( stat.subClass );
00865     uint32_t hIdx = CodingStatisticsClassType::GetSubClassHeight( stat.subClass );
00866 
00867     s.pixels = s.count * gp_sizeIdxInfo->sizeFrom( wIdx ) * gp_sizeIdxInfo->sizeFrom( hIdx );
00868   }
