00870   StatLogValue values;
00871 
00872   static void UpdateCABACStat( const CodingStatisticsClassType &stat, uint32_t uiRangeBefore, uint32_t uiRangeAfter, int val )
00873   {
00874     CHECK( stat.type == STATS__CABAC_BITS__INVALID, "Should never be used." );
00875     CodingStatistics &inst = GetSingletonInstance();
00876     // doing rangeBefore*p(x)=rangeAfter
00877     // p(x)=rangeAfter/rangeBefore
00878     // entropy = -log2(p(x))=-log(p(x))/log(2) = -(log rangeAfter - log rangeBefore) / log(2) = (log rangeBefore / log 2 - log rangeAfter / log 2)
00879     SStat &s = inst.data.statistics[stat.type][stat.subClass];
00880     s.bits  += inst.values.values[uiRangeBefore] - inst.values.values[uiRangeAfter];
00881     s.count++;
00882     s.sum   += val;
00883   }
00884 
00885 #if RExt__DECODER_DEBUG_TOOL_MAX_FRAME_STATS
00886   static void UpdateMaxStat(CodingStatisticsData *data)
00887   {
00888     SStat_max &   max = GetStatisticMax();
00889     const int64_t es = CODINGSTATISTICS_ENTROPYSCALE;
00890 
00891     int64_t countTotal = 0;
00892     int64_t classCounts[STATS__NUM_STATS];
00893     std::fill_n(classCounts, (size_t) STATS__NUM_STATS, 0);
00894 
00895     int64_t cr = 0;   // CABAC remainder, which is added to "STATS__CABAC_INITIALISATION"
00896 
00897     int64_t totalCABACbits = 0, roundedCABACbits = 0;
00898     for (int i = STATS__NAL_UNIT_PACKING; i < STATS__NUM_STATS; i++)
00899     {
00900       int64_t classCount = 0;
00901 
00902       for (uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c++)
00903       {
00904         totalCABACbits += data->statistics[i][c].bits;
00905         roundedCABACbits += data->statistics[i][c].bits / es;
00906         classCount += data->statistics[i][c].count;
00907       }
00908 
00909       for (uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c++)
00910       {
00911         data->statistics[i][c].classCount = classCount;
00912       }
00913 
00914       classCounts[i] = classCount;
00915       countTotal += classCount;
00916     }
00917     int64_t remainder = totalCABACbits - roundedCABACbits * es;
00918     cr = (remainder + es / 2) / es;
00919 
00920     classCounts[0] = countTotal;
00921 
00922     SStat cabacTotalBits, epTotalBits, cabacTrfTotalBits, epTrfTotalBits;
00923 
00924     cabacTotalBits.classCount = countTotal;
00925     epTotalBits.classCount = countTotal;
00926     cabacTrfTotalBits.classCount = countTotal;
00927     epTrfTotalBits.classCount    = countTotal;
00928 
00929     // Calculate the actual bin and bit count
00930     for (int i = 0; i < STATS__NUM_STATS; i++)
00931     {
00932       for (uint32_t c = 0; c < CODING_STATS_NUM_SUBCLASSES; c++)
00933       {
00934         SStat &sCABACorig = data->statistics[i][c];
00935         SStat &sEP = data->statistics_ep[i][c];
00936 
00937         if (sCABACorig.bits == 0 && sEP.bits == 0)
00938         {
00939           continue;
00940         }
00941 
00942         SStat sCABAC;
00943         {
00944           int64_t thisCABACbits = sCABACorig.bits / es;
00945           if (i == STATS__CABAC_INITIALISATION && sCABACorig.bits != 0)
00946           {
00947             thisCABACbits += cr;
00948 #if EPBINCOUNT_FIX
00949             sCABACorig.count = 0;
00950 #endif
00951             cr = 0;
00952           }
00953           sCABAC.bits = thisCABACbits;
00954           sCABAC.count = sCABACorig.count;
00955           sCABAC.sum = sCABACorig.sum;
00956           sCABAC.classCount = classCounts[i];
00957         }
00958 #if EPBINCOUNT_FIX
00959         if ( i == STATS__BYTE_ALIGNMENT_BITS || i == STATS__TRAILING_BITS || i == STATS__NAL_UNIT_HEADER_BITS || i == STATS__EMULATION_PREVENTION_3_BYTES )
00960         {
00961           sEP.count = 0;
00962         }
00963 #endif
00964 
00965         if( i != STATS__NAL_UNIT_TOTAL_BODY )
00966         {
00967           cabacTotalBits += sCABAC;
00968           epTotalBits += sEP;
00969 
00970          // For TRF
00971          if ((i == STATS__CABAC_BITS__SIG_COEFF_MAP_FLAG) || (i == STATS__CABAC_BITS__PAR_FLAG)
00972              || (i == STATS__CABAC_BITS__GT1_FLAG) || (i == STATS__CABAC_BITS__GT2_FLAG)
00973              || (i == STATS__CABAC_BITS__ESCAPE_BITS))
00974          {
00975            cabacTrfTotalBits += sCABAC;
00976            epTrfTotalBits += sEP;
00977          }
00978         }
00979       }
00980     }
00981 
00982     SStat delta_CABAC = cabacTotalBits;
00983     SStat delta_EP = epTotalBits;
00984     SStat delta_trf_CABAC = cabacTrfTotalBits;
00985     SStat delta_trf_EP = epTrfTotalBits;
00986 
00987     delta_CABAC -= max.prev_CABAC_state;
00988     delta_EP -= max.prev_EP_state;
00989 
00990     delta_trf_CABAC -= max.prev_trf_CABAC_state;
00991     delta_trf_EP -= max.prev_trf_EP_state;
00992     int64_t max_frame_bins = EPBIN_WEIGHT_FACTOR * max.max_CABAC_state.count + max.max_EP_state.count;
00993     int64_t cur_frame_bins = EPBIN_WEIGHT_FACTOR * delta_CABAC.count + delta_EP.count;
00994 
00995     if (cur_frame_bins > max_frame_bins)
00996     {
00997       max.max_CABAC_state = delta_CABAC;
